class Solution {
public:
    unordered_map<long long, long long> memo;
    int k;
    int waysToReachStair(int kk) {
        k = kk;
        return (int) dfs(1, 0, false);
    }
    long long dfs(long long pos, int jump, bool down) {
        if (pos > k + 1 || (1LL << jump) > k + 1) return pos == k ? 1 : 0;
        long long key = pos * 200 + jump * 2 + down;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        long long res = (pos == k) ? 1 : 0;
        if (pos > 0 && !down) res += dfs(pos - 1, jump, true);
        res += dfs(pos + (1LL << jump), jump + 1, false);
        return memo[key] = res;
    }
};

