class Solution {
    private final Map<Long, Long> memo = new HashMap<>();
    private int k;
    public int waysToReachStair(int k) {
        this.k = k;
        return (int) dfs(1, 0, false);
    }
    private long dfs(long pos, int jump, boolean down) {
        if (pos > k + 1 || (1L << jump) > k + 1) return pos == k ? 1 : 0;
        long key = pos * 200 + jump * 2L + (down ? 1 : 0);
        Long got = memo.get(key);
        if (got != null) return got;
        long res = (pos == k) ? 1 : 0;
        if (pos > 0 && !down) res += dfs(pos - 1, jump, true);
        res += dfs(pos + (1L << jump), jump + 1, false);
        memo.put(key, res);
        return res;
    }
}

