var waysToReachStair = function(k) {
    const memo = new Map();
    const dfs = (pos, jump, down) => {
        if (pos > k + 1 || (1 << jump) > k + 1) return pos === k ? 1 : 0;
        const key = pos * 200 + jump * 2 + (down ? 1 : 0);
        if (memo.has(key)) return memo.get(key);
        let res = pos === k ? 1 : 0;
        if (pos > 0 && !down) res += dfs(pos - 1, jump, true);
        res += dfs(pos + (1 << jump), jump + 1, false);
        memo.set(key, res);
        return res;
    };
    return dfs(1, 0, false);
};

