class Solution:
    def waysToReachStair(self, k: int) -> int:
        import math
        ans = 0
        m = 0
        while (1 << m) - k <= m + 1:
            d = (1 << m) - k
            if d >= 0:
                ans += math.comb(m + 1, d)
            m += 1
        return ans

