class Solution {
public:
    int waysToReachStair(int k) {
        long long ans = 0;
        for (int m = 0; ; m++) {
            long long d = (1LL << m) - k;
            if (d > m + 1) break;
            if (d >= 0) {
                long long c = 1;
                for (int i = 0; i < d; i++) c = c * (m + 1 - i) / (i + 1);
                ans += c;
            }
        }
        return (int) ans;
    }
};

